documents.id:
yamaa: '1.0'
type: function
name: id
description: Integer identity.
params: [{name: x, type: int}]
returns: int
implementations: {python: project.id}
tests:
  - {id: ordinary, covers: [normal], args: {x: 7}, result: 7}
  - {id: boundary, covers: [boundary], args: {x: -9223372036854775808}, result: -9223372036854775808}
  - {id: missing, covers: ['short-circuit-missing:x'], args: {x: null}, result: null}

documents.pair:
yamaa: '1.0'
type: function
name: pair
description: Integer sum of a weight and an own value.
params: [{name: weight, type: int}, {name: own, type: int}]
returns: int
implementations: {python: project.pair}
tests:
  - {id: ordinary, covers: [normal], args: {weight: 7, own: 3}, result: 10}
  - {id: boundary, covers: [boundary], args: {weight: 0, own: 0}, result: 0}
  - {id: missing-weight, covers: ['short-circuit-missing:weight'], args: {weight: null, own: 1}, result: null}
  - {id: missing-own, covers: ['short-circuit-missing:own'], args: {weight: 1, own: null}, result: null}

documents.domain:
yamaa: '1.0'
type: spec
domain: TEST
input: {SRC: {path: input.csv, types: {ID: int}}}
keys: [ID]
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: VALUE, type: int, derivation: {function: {name: id, args: {x: SRC.ID}}}}
output: {path: output.csv, columns: [ID, VALUE]}

documents.aggregate:
yamaa: '1.0'
type: spec
domain: TEST
input: {SRC: {path: input.csv, key: [ID], types: {ID: int}}}
keys: [ID]
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - name: VALUE
    type: int
    derivation:
      aggregate:
        derivations:
          BASE: {type: int, derivation: SRC.ID}
          V: {type: int, derivation: {function: {name: id, args: {x: SRC.ID}}}}
        expr: SUM(V)
output: {path: output.csv, columns: [ID, VALUE]}

documents.join:
yamaa: '1.0'
type: spec
domain: TEST
input:
  SRC: {path: a.csv, key: [ID], types: {ID: int, N: int}}
  B: {path: b.csv, key: [ID], types: {ID: int, N: int}}
base: SRC
keys: [ID]
columns:
  - {name: ID, type: int}
  - {name: VALUE, type: int}
rows:
  - id: records
    dataset: SRC
    derivations:
      ID: SRC.ID
      VALUE: {function: {name: id, args: {x: B.N}}}
output: {path: output.csv, columns: [ID, VALUE]}

